struct Stack<Element> {
    var items: [Element] = []
    mutating func push(_ item: Element) { items.append(item) }
}
extension Stack {
    var count: Int { items.count }
}
var s = Stack<String>()
s.push("Swift")
s.push("Generics")
print(s.count)

func findFirst<T: Comparable>(in array: [T]) -> T? {
    array.sorted().first
}
let numbers = [5, 2, 8, 1, 9]
print(findFirst(in: numbers) ?? 0)

