struct Stack<T> {
    private var items: [T] = []
    mutating func push(_ item: T) {
        items.append(item)
    }
    mutating func pop() -> T? {
        return items.popLast()
    }
}
var s = Stack<Int>()
s.push(100)
s.push(200)
print(s.pop() ?? 0)
print(s.pop() ?? 0)

func findIndex<T: Equatable>(of target: T, in array: [T]) -> Int? {
    for (index, item) in array.enumerated() {
        if item == target {
            return index
        }
    }
    return nil
}
let names = ["Taylor", "Chris", "Sam"]
print(findIndex(of: "Chris", in: names) ?? -1)
print(findIndex(of: "Alex", in: names) ?? -1)
